const rootSelectors = ['#app-shell', '#app-sheet'];
const skipped = 'script,style,canvas,svg,textarea,input,[contenteditable],#settings-screen,[data-no-translate],.chat-log,.voice-transcript,.companion-history,.auth-account-copy,.auth-avatar,.card-profile-copy h2,.card-profile-copy>p,.card-profile-facts,.card-record,.card-record-detail,.card-entry-details dd,.card-entry-meta,.card-essentials dd,.account-box strong,.account-box small';
const textHistory = new WeakMap();
const attributeHistory = new WeakMap();
const observedAttributes = ['aria-label', 'placeholder', 'title'];
let language = 'en';
let observer = null;
let scheduled = false;
let destroyed = false;

function translation(source) {
  const text = source.trim();
  if (!Object.hasOwn(chinese, text)) return source;
  return source.replace(text, chinese[text]);
}
function ignored(element) {
  return !element || Boolean(element.closest(skipped));
}
function translateText(node) {
  const parent = node.parentElement;
  if (ignored(parent) || (parent.tagName === 'OPTION' && !parent.hasAttribute('value'))) return;
  if (parent.id === 'sheet-title' && document.querySelector('#app-sheet .card-entry-details')) return;
  const previous = textHistory.get(node);
  const current = node.nodeValue || '';
  const source = previous && previous.rendered === current ? previous.source : current;
  const rendered = language === 'zh' ? translation(source) : source;
  if (rendered !== current) node.nodeValue = rendered;
  if (rendered !== source || previous) textHistory.set(node, { source, rendered });
}
function translateAttributes(element) {
  // Inputs may have localized hints, but their values are never read or changed.
  if (element.closest('#settings-screen,[data-no-translate],.chat-log,.voice-transcript,.companion-history,.auth-account-copy,.card-record')) return;
  let history = attributeHistory.get(element);
  for (const name of observedAttributes) {
    const current = element.getAttribute(name);
    if (current === null) continue;
    const previous = history?.[name];
    const source = previous && previous.rendered === current ? previous.source : current;
    const rendered = language === 'zh' ? translation(source) : source;
    if (rendered !== current) element.setAttribute(name, rendered);
    if (rendered !== source || previous) {
      history ||= {};
      history[name] = { source, rendered };
    }
  }
  if (history) attributeHistory.set(element, history);
}
function apply() {
  scheduled = false;
  if (destroyed || typeof document === 'undefined') return;
  observer?.disconnect();
  for (const selector of rootSelectors) {
    const root = document.querySelector(selector);
    if (!root) continue;
    translateAttributes(root);
    const walker = document.createTreeWalker(root, 1 | 4);
    for (let node = walker.nextNode(); node; node = walker.nextNode()) {
      if (node.nodeType === 3) translateText(node);
      else translateAttributes(node);
    }
    observer?.observe(root, { subtree:true, childList:true, characterData:true, attributes:true, attributeFilter:observedAttributes });
  }
}

/** Call on account selection and preference changes. English is the default. */
export function setInterfaceLanguage(value = 'en') {
  language = value === 'zh' ? 'zh' : 'en';
  destroyed = false;
  if (typeof document === 'undefined') return language;
  document.documentElement.lang = language === 'zh' ? 'zh-CN' : 'en';
  if (!observer && typeof MutationObserver !== 'undefined') {
    observer = new MutationObserver(() => {
      if (!scheduled) { scheduled = true; queueMicrotask(apply); }
    });
  }
  apply();
  return language;
}
export function disconnectInterfaceLanguage() {
  destroyed = true;
  scheduled = false;
  observer?.disconnect();
  observer = null;
}
